#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    string secret;
    cin >> secret;
    string guess;
    cin >> guess;

    int bulls = 0, cs[10] = {0}, cg[10] = {0};
    for (size_t i = 0; i < secret.size(); i++) {
        if (secret[i] == guess[i]) bulls++;
        cs[secret[i] - '0']++;
        cg[guess[i] - '0']++;
    }
    int common = 0;
    for (int d = 0; d < 10; d++) common += min(cs[d], cg[d]);
    cout << bulls << " " << common - bulls << "\n";

    return 0;
}

